\begin{tikzpicture}[font=\sffamily\small,line cap=round,line join=round,>=stealth]
% concave mirror (reflecting face toward Sun on the right)
\draw[thick] (0.4,0.2) .. controls (1.7,1.6) .. (0.4,3.0);
\foreach \y in {0.45,0.85,1.25,1.65,2.05,2.45,2.75} {\draw[thin] (0.35,\y)--++(-0.25,0.05);}
\node[font=\footnotesize] at (0.15,3.35) {concave mirror};
% parallel sun rays in from the right
\draw[->,thick] (5.6,2.55)--(1.35,2.55);
\draw[->,thick] (5.6,1.6)--(1.55,1.6);
\draw[->,thick] (5.6,0.65)--(1.35,0.65);
\node at (5.95,1.6) {Sun};
% reflected rays meet on leaf at focus
\draw[->,thick] (1.35,2.55)--(3.35,1.6);
\draw[->,thick] (1.55,1.6)--(3.35,1.6);
\draw[->,thick] (1.35,0.65)--(3.35,1.6);
\fill (3.35,1.6) circle (1.6pt);
\draw[thick,fill=green!20] (3.15,1.25) rectangle (3.55,1.95);
\node[font=\footnotesize] at (3.35,1.0) {leaf};
\node[font=\footnotesize] at (4.15,2.05) {focus};
